// src/components/common/ClaimCard.jsx
import React, { useState, useRef, useEffect } from 'react';
import './ClaimCard.css';

const ClaimCard = ({ claim, representative, onAddPayment, showPopup, onOptionSelect, popupVisible, popupProgress }) => {
  const [isPopupOpen, setIsPopupOpen] = useState(false);
  const popupRef = useRef(null);
  const buttonRef = useRef(null);

  if (!claim) return null;

  const name = claim.covernote_request?.PolicyHolder?.policy_holder_name || 'Lupo Chambaka';
  const phone = claim.msisdn || '255781518973';
  const claimDate = claim.created_at || '2025-12-03 13:53:34';
  const ref = claim.covert_note_number || '135402-251203-592423';
  const rep = representative || 'Shabani';

  const handleButtonClick = () => {
    setIsPopupOpen(true);
    if (onAddPayment) onAddPayment();
  };

  const handleOptionClick = (option) => {
    setIsPopupOpen(false);
    if (onOptionSelect) onOptionSelect(option);
  };

  // Close popup when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (popupRef.current && !popupRef.current.contains(event.target) && 
          buttonRef.current && !buttonRef.current.contains(event.target)) {
        setIsPopupOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Close popup when popupVisible becomes false (auto-dismiss)
  useEffect(() => {
    if (!popupVisible && isPopupOpen) {
      setIsPopupOpen(false);
    }
  }, [popupVisible, isPopupOpen]);

  return (
    <div className="claim-card">
      <div className="claim-ref">{ref}</div>
      <div className="claim-detail">
        <span className="label">Customer</span>
        <span className="value">{name}</span>
      </div>
      <div className="claim-detail">
        <span className="label">Phone</span>
        <span className="value">{phone}</span>
      </div>
      <div className="claim-detail">
        <span className="label">Claim Date</span>
        <span className="value">{claimDate}</span>
      </div>
      <div className="claim-detail">
        <span className="label">Representative</span>
        <span className="value">{rep}</span>
      </div>
      <div className="claim-detail">
        <span className="label">Reason</span>
        <span className="value">Claim</span>
      </div>
      <div className="card-actions" style={{ position: 'relative' }}>
        <button 
          ref={buttonRef}
          className="btn-primary" 
          onClick={handleButtonClick}
        >
          <i className="fas fa-plus-circle"></i> Add Payment
        </button>
        
        {/* Popup dropdown below the button */}
        {isPopupOpen && (
          <div ref={popupRef} className="popup-dropdown">
            <div className="popup-dropdown-content">
              <div className="popup-title">Choose claim type</div>
              <button 
                className="popup-option-btn" 
                onClick={() => handleOptionClick('Replacement')}
              >
                <i className="fas fa-exchange-alt"></i> Replacement
              </button>
              <button 
                className="popup-option-btn" 
                onClick={() => handleOptionClick('Repair')}
              >
                <i className="fas fa-tools"></i> Repair
              </button>
              <div className="popup-timer">
                <div className="popup-progress-bar">
                  <div 
                    className="popup-progress-fill" 
                    style={{ width: `${popupProgress || 0}%` }}
                  />
                </div>
                <span className="popup-timer-text">Auto-dismissing in {Math.ceil((100 - (popupProgress || 0)) / 25)}s</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ClaimCard;
